CREATE TABLE semio_model_document (id INTEGER PRIMARY KEY, schema TEXT NOT NULL);
CREATE TABLE semio_model_entity (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_model_document(id), kind TEXT NOT NULL CHECK (kind IN ('spatial','element')), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), native_id TEXT NOT NULL);
CREATE TABLE semio_model_spatial (id INTEGER PRIMARY KEY REFERENCES semio_model_entity(id), kind TEXT NOT NULL CHECK (kind IN ('site','building','storey','space')), name TEXT NOT NULL, parent_id INTEGER REFERENCES semio_model_spatial(id));
CREATE TABLE semio_model_element (id INTEGER PRIMARY KEY REFERENCES semio_model_entity(id), class TEXT NOT NULL CHECK (class IN ('wall','slab','column','beam','door','window','roof','stair','furniture','other')), other_class_name TEXT, spatial_id INTEGER REFERENCES semio_model_spatial(id));
CREATE TABLE semio_model_placement (id INTEGER PRIMARY KEY REFERENCES semio_model_entity(id), translation_x REAL, translation_y REAL, translation_z REAL, rotation_x REAL, rotation_y REAL, rotation_z REAL, rotation_w REAL, scale_x REAL, scale_y REAL, scale_z REAL, translation_x_ieee754_bits INTEGER, translation_x_numeric_class TEXT, translation_y_ieee754_bits INTEGER, translation_y_numeric_class TEXT, translation_z_ieee754_bits INTEGER, translation_z_numeric_class TEXT, rotation_x_ieee754_bits INTEGER, rotation_x_numeric_class TEXT, rotation_y_ieee754_bits INTEGER, rotation_y_numeric_class TEXT, rotation_z_ieee754_bits INTEGER, rotation_z_numeric_class TEXT, rotation_w_ieee754_bits INTEGER, rotation_w_numeric_class TEXT, scale_x_ieee754_bits INTEGER, scale_x_numeric_class TEXT, scale_y_ieee754_bits INTEGER, scale_y_numeric_class TEXT, scale_z_ieee754_bits INTEGER, scale_z_numeric_class TEXT);
CREATE TABLE semio_model_geometry_reference (id INTEGER PRIMARY KEY REFERENCES semio_model_element(id), kind TEXT NOT NULL CHECK (kind IN ('none','brep','mesh')), target_native_id TEXT);
CREATE TABLE semio_model_property_set (id INTEGER PRIMARY KEY, element_id INTEGER NOT NULL REFERENCES semio_model_element(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), name TEXT NOT NULL);
CREATE TABLE semio_model_property (id INTEGER PRIMARY KEY, property_set_id INTEGER NOT NULL REFERENCES semio_model_property_set(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), property_key TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('text','number','boolean')), text_value TEXT, number_value REAL, boolean_value INTEGER CHECK (boolean_value IN (0,1)), number_value_ieee754_bits INTEGER, number_value_numeric_class TEXT);
CREATE TABLE semio_model_relation (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_model_document(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), native_id TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('aggregates','contained_in','connects_to','fills_void','voids_element','other')), other_label TEXT, source_entity_id INTEGER NOT NULL REFERENCES semio_model_entity(id), target_entity_id INTEGER NOT NULL REFERENCES semio_model_entity(id));
